class ExactVectorInputPolicy(unittest.TestCase):
    def setUp(self):
        self.data=copy.deepcopy(FIXTURE);self.run=self.data['run'];self.jobs=self.data['jobs'];self.arts=self.data['artifacts'];self.job=next(j for j in self.jobs if j['id']==121841617606);self.art=next(a for a in self.arts if a['id']==12696439886);self.now=datetime(2026,10,27,tzinfo=timezone.utc)
        self.lock={'id':'vector','version':'0.11.0-bogo.2','bogoOverlay':{'sourceTreeSha256':'48d62e620b68a00be8c65bb5a0065747be7169112c252640e9fd954b0c0ac2ee','patchSha256':'ce31e148556a2b1f98dc92b78a937eeb847ec3950ed13bfeee3f34acc44b580d'}}
    def test_exact_completed_api_metadata_is_input_eligible_not_accepted(self):
        r=gate.validate_run(self.run,40399110833,'0a2089a8c2ef0e2835438d0fe2733fd963b61866','vector');j=gate.select_job(self.jobs,r,'vector');a=gate.validate_artifact(self.art,r,j,'vector',self.now)
        self.assertEqual(a['id'],12696439886);old=gate.job_eligibility(j,'vector');self.assertFalse(old['priorNativeAcceptancePassed']);self.assertTrue(old['freshFullAcceptanceRequired']);self.assertEqual(old['priorJobConclusion'],'failure')
        source=gate.vector_timeout_source_binding(r,self.jobs,self.arts,'vector',self.lock,self.now);self.assertEqual(source['sourceArtifact']['id'],12688201983);self.assertEqual(len(source['sourceFiles']),4);self.assertFalse(source['sourceFilesRehashedByThisWindowsCollector']);self.assertTrue(source['finalGateMustVerifyActualSource4'])
    def test_only_exact_app_run_head_branch_attempt_workflow_status_repo_tuple(self):
        self.assertFalse(gate.exact_vector_timeout_input(self.run,'photo'))
        for key,value in [('id',40399110834),('head_sha','0'*40),('head_branch','codex/bogo-vector-timeout-other'),('run_attempt',2),('workflow_id',1),('status','in_progress'),('conclusion','success')]:
            changed={**self.run,key:value}
            self.assertFalse(gate.exact_vector_timeout_input(changed,'vector'))
            with self.subTest(key=key),self.assertRaises(gate.Refused):gate.validate_run(changed,changed['id'],changed['head_sha'],'vector')
        for key in ('repository','head_repository'):
            changed=copy.deepcopy(self.run);changed[key]['full_name']='other/repo'
            with self.assertRaises(gate.Refused):gate.validate_run(changed,40399110833,self.run['head_sha'],'vector')
    def test_original_standard_branch_behavior_remains(self):
        normal={**self.run,'head_branch':gate.BRANCH,'status':'in_progress','conclusion':None}
        self.assertEqual(gate.validate_run(normal,normal['id'],normal['head_sha']),normal)
    def test_exact_job_id_and_only_failed_smoke_step_required(self):
        for key,value in [('id',1),('run_attempt',2),('head_sha','0'*40),('labels',['self-hosted']),('conclusion','cancelled')]:
            data=copy.deepcopy(self.jobs);j=next(x for x in data if x['id']==121841617606);j[key]=value
            with self.subTest(key=key),self.assertRaises(gate.Refused):gate.select_job(data,self.run,'vector')
        data=copy.deepcopy(self.jobs);j=next(x for x in data if x['id']==121841617606);next(s for s in j['steps']if s['number']==11)['number']=13
        with self.assertRaises(gate.Refused):gate.select_job(data,self.run,'vector')
    def test_build_package_verify_upload_failure_or_skip_never_eligible(self):
        for number in (3,6,7,8,9,10,12):
            for conclusion in ('failure','skipped','cancelled','timed_out'):
                data=copy.deepcopy(self.jobs);j=next(x for x in data if x['id']==121841617606);next(s for s in j['steps']if s['number']==number)['conclusion']=conclusion
                with self.subTest(number=number,conclusion=conclusion),self.assertRaises(gate.Refused):gate.select_job(data,self.run,'vector')
    def test_other_artifact_id_digest_size_expiry_branch_or_app_rejected(self):
        for key,value in [('id',1),('digest','sha256:'+'0'*64),('size_in_bytes',220164188),('expired',True),('name','bogo-photo-windows-x64')]:
            with self.subTest(key=key),self.assertRaises(gate.Refused):gate.validate_artifact({**self.art,key:value},self.run,self.job,'vector',self.now)
        art=copy.deepcopy(self.art);art['workflow_run']['head_branch']=gate.BRANCH
        with self.assertRaises(gate.Refused):gate.validate_artifact(art,self.run,self.job,'vector',self.now)
    def test_source_current_row_and_source4_artifact_binding_required(self):
        for key in ('sourceTreeSha256','patchSha256'):
            lock=copy.deepcopy(self.lock);lock['bogoOverlay'][key]='0'*64
            with self.assertRaises(gate.Refused):gate.vector_timeout_source_binding(self.run,self.jobs,self.arts,'vector',lock,self.now)
        for key,value in [('id',1),('digest','sha256:'+'0'*64),('size_in_bytes',1),('expired',True)]:
            data=copy.deepcopy(self.arts);a=next(a for a in data if a['id']==12688201983);a[key]=value
            with self.subTest(key=key),self.assertRaises(gate.Refused):gate.vector_timeout_source_binding(self.run,self.jobs,data,'vector',self.lock,self.now)
    def test_source_job_any_failed_or_missing_mandatory_step_rejected(self):
        data=copy.deepcopy(self.jobs);j=next(x for x in data if x['id']==121841617688);j['conclusion']='failure'
        with self.assertRaises(gate.Refused):gate.vector_timeout_source_binding(self.run,data,self.arts,'vector',self.lock,self.now)
        data=copy.deepcopy(self.jobs);j=next(x for x in data if x['id']==121841617688);j['steps']=[s for s in j['steps']if ' source --app vector'not in s['name']]
        with self.assertRaises(gate.Refused):gate.vector_timeout_source_binding(self.run,data,self.arts,'vector',self.lock,self.now)
    def test_normal_ref_is_not_reclassified_as_timeout_exception(self):
        run={**self.run,'head_branch':gate.BRANCH};self.assertIsNone(gate.vector_timeout_source_binding(run,[],[],'vector',{},self.now))
