        import os
        from unittest.mock import patch
        env={'GITHUB_ACTIONS':'true','RUNNER_OS':'Windows','RUNNER_ENVIRONMENT':'github-hosted','GITHUB_REPOSITORY':gate.REPOSITORY,'GITHUB_WORKFLOW':gate.WORKFLOW,'GITHUB_EVENT_NAME':'workflow_dispatch','GITHUB_REF':'refs/heads/codex/bogo-vector-timeout-20261027'}
        with patch.object(gate.sys,'platform','win32'),patch.dict(os.environ,env,clear=True),self.assertRaises(gate.Refused):
            gate.runner_context()
